import{_ as o,c as a,o as s,j as i,Y as n,t as r}from"./chunks/framework.D-NV0Bun.js";const g=JSON.parse('{"title":"nscd.conf | x-cmd man (man5) | name service cache daemon configuration file","titleTemplate":false,"description":"x-cmd man (man5 Manual Page) | nscd.conf - name service cache daemon configuration file","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"nscd.conf | x-cmd man (man5) | name service cache daemon configuration file"}],["meta",{"name":"og:description","content":"x-cmd man (man5 Manual Page) | nscd.conf - name service cache daemon configuration file"}]]},"headers":[],"params":{"isMan":true,"man":"nscd.conf","category":"man5","desc":"name service cache daemon configuration file"},"relativePath":"man5/nscd.conf.md","filePath":"man5/[man].md"}'),c={name:"man5/nscd.conf.md"},l={class:"visually-hidden"};function m(t,e,d,h,u,p){return s(),a("div",null,[i("h1",l,r(t.$params.man),1),e[0]||(e[0]=n('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>nscd.conf - name service cache daemon configuration file</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The file <em>/etc/nscd.conf</em> is read from <strong>nscd</strong>(8) at startup. Each line specifies either an attribute and a value, or an attribute, service, and a value. Fields are separated either by SPACE or TAB characters. A &#39;#&#39; (number sign) indicates the beginning of a comment; following characters, up to the end of the line, are not interpreted by nscd.</p><p>Valid services are <em>passwd</em>, <em>group</em>, <em>hosts</em>, <em>services</em>, or <em>netgroup</em>.</p><p><strong>logfile</strong> <em>debug-file-name</em></p><blockquote><p>Specifies name of the file to which debug info should be written.</p></blockquote><p><strong>debug-level</strong> <em>value</em></p><blockquote><p>Sets the desired debug level. 0 hides debug info. 1 shows general debug info. 2 additionally shows data in cache dumps. 3 (and above) shows all debug info. The default is 0.</p></blockquote><p><strong>threads</strong> <em>number</em></p><blockquote><p>This is the initial number of threads that are started to wait for requests. At least five threads will always be created. The number of threads may increase dynamically up to <strong>max-threads</strong> in response to demand from clients, but never decreases.</p></blockquote><p><strong>max-threads</strong> <em>number</em></p><blockquote><p>Specifies the maximum number of threads. The default is 32.</p></blockquote><p><strong>server-user</strong> <em>user</em></p><blockquote><p>If this option is set, nscd will run as this user and not as root. If a separate cache for every user is used (-S parameter), this option is ignored.</p></blockquote><p><strong>stat-user</strong> <em>user</em></p><blockquote><p>Specifies the user who is allowed to request statistics.</p></blockquote><p><strong>reload-count</strong> unlimited | <em>number</em></p><blockquote><p>Sets a limit on the number of times a cached entry gets reloaded without being used before it gets removed. The limit can take values ranging from 0 to 254; values 255 or higher behave the same as <strong>unlimited</strong>. Limit values can be specified in either decimal or hexadecimal with a &quot;0x&quot; prefix. The special value <strong>unlimited</strong> is case-insensitive. The default limit is 5. A limit of 0 turns off the reloading feature. See NOTES below for further discussion of reloading.</p></blockquote><p><strong>paranoia</strong> <em>&lt;yes|no&gt;</em></p><blockquote><p>Enabling paranoia mode causes nscd to restart itself periodically. The default is no.</p></blockquote><p><strong>restart-interval</strong> <em>time</em></p><blockquote><p>Sets the restart interval to <em>time</em> seconds if periodic restart is enabled by enabling <strong>paranoia</strong> mode. The default is 3600.</p></blockquote><p><strong>enable-cache</strong> <em>service</em> <em>&lt;yes|no&gt;</em></p><blockquote><p>Enables or disables the specified <em>service</em> cache. The default is no.</p></blockquote><p><strong>positive-time-to-live</strong> <em>service</em> <em>value</em></p><blockquote><p>Sets the TTL (time-to-live) for positive entries (successful queries) in the specified cache for <em>service</em>. <em>Value</em> is in seconds. Larger values increase cache hit rates and reduce mean response times, but increase problems with cache coherence. Note that for some name services (including specifically DNS) the TTL returned from the name service is used and this attribute is ignored.</p></blockquote><p><strong>negative-time-to-live</strong> <em>service</em> <em>value</em></p><blockquote><p>Sets the TTL (time-to-live) for negative entries (unsuccessful queries) in the specified cache for <em>service</em>. <em>Value</em> is in seconds. Can result in significant performance improvements if there are several files owned by UIDs (user IDs) not in system databases (for example untarring the Linux kernel sources as root); should be kept small to reduce cache coherency problems.</p></blockquote><p><strong>suggested-size</strong> <em>service</em> <em>value</em></p><blockquote><p>This is the internal hash table size, <em>value</em> should remain a prime number for optimum efficiency. The default is 211.</p></blockquote><p><strong>check-files</strong> <em>service</em> <em>&lt;yes|no&gt;</em></p><blockquote><p>Enables or disables checking the file belonging to the specified <em>service</em> for changes. The files are <em>/etc/passwd</em>, <em>/etc/group</em>, <em>/etc/hosts</em>, <em>/etc/resolv.conf</em>, <em>/etc/services</em>, and <em>/etc/netgroup</em>. The default is yes.</p></blockquote><p><strong>persistent</strong> <em>service</em> <em>&lt;yes|no&gt;</em></p><blockquote><p>Keep the content of the cache for <em>service</em> over server restarts; useful when <strong>paranoia</strong> mode is set. The default is no.</p></blockquote><p><strong>shared</strong> <em>service</em> <em>&lt;yes|no&gt;</em></p><blockquote><p>The memory mapping of the nscd databases for <em>service</em> is shared with the clients so that they can directly search in them instead of having to ask the daemon over the socket each time a lookup is performed. The default is no. Note that a cache miss will still result in asking the daemon over the socket.</p></blockquote><p><strong>max-db-size</strong> <em>service</em> <em>bytes</em></p><blockquote><p>The maximum allowable size, in bytes, of the database files for the <em>service</em>. The default is 33554432.</p></blockquote><p><strong>auto-propagate</strong> <em>service</em> <em>&lt;yes|no&gt;</em></p><blockquote><p>When set to <em>no</em> for <em>passwd</em> or <em>group</em> service, then the <em>.byname</em> requests are not added to <em>passwd.byuid</em> or <em>group.bygid</em> cache. This can help with tables containing multiple records for the same ID. The default is yes. This option is valid only for services <em>passwd</em> and <em>group</em>.</p></blockquote><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>The default values stated in this manual page originate from the source code of <strong>nscd</strong>(8) and are used if not overridden in the configuration file. The default values used in the configuration file of your distribution might differ.</p><h3 id="reloading" tabindex="-1">Reloading <a class="header-anchor" href="#reloading" aria-label="Permalink to &quot;Reloading&quot;">​</a></h3><p><strong>nscd</strong>(8) has a feature called reloading, whose behavior can be surprising.</p><p>Reloading is enabled when the <strong>reload-count</strong> attribute has a non-zero value. The default value in the source code enables reloading, although your distribution may differ.</p><p>When reloading is enabled, positive cached entries (the results of successful queries) do not simply expire when their TTL is up. Instead, at the expiry time, <strong>nscd</strong> will &quot;reload&quot;, i.e., re-issue to the name service the same query that created the cached entry, to get a new value to cache. Depending on <em>/etc/nsswitch.conf</em> this may mean that a DNS, LDAP, or NIS request is made. If the new query is successful, reloading will repeat when the new value would expire, until <strong>reload-count</strong> reloads have happened for the entry, and only then will it actually be removed from the cache. A request from a client which hits the entry will reset the reload counter on the entry. Purging the cache using <em>nscd -i</em> overrides the reload logic and removes the entry.</p><p>Reloading has the effect of extending cache entry TTLs without compromising on cache coherency, at the cost of additional load on the backing name service. Whether this is a good idea on your system depends on details of your applications&#39; behavior, your name service, and the effective TTL values of your cache entries. Note that for some name services (for example, DNS), the effective TTL is the value returned from the name service and <em>not</em> the value of the <strong>positive-time-to-live</strong> attribute.</p><p>Please consider the following advice carefully:</p><ul><li><p>If your application will make a second request for the same name, after more than 1 TTL but before <strong>reload-count</strong> TTLs, and is sensitive to the latency of a cache miss, then reloading may be a good idea for you.</p></li><li><p>If your name service is configured to return very short TTLs, and your applications only make requests rarely under normal circumstances, then reloading may result in additional load on your backing name service without any benefit to applications, which is probably a bad idea for you.</p></li><li><p>If your name service capacity is limited, reloading may have the surprising effect of increasing load on your name service instead of reducing it, and may be a bad idea for you.</p></li><li><p>Setting <strong>reload-count</strong> to <strong>unlimited</strong> is almost never a good idea, as it will result in a cache that never expires entries and puts never-ending additional load on the backing name service.</p></li></ul><p>Some distributions have an init script for <strong>nscd</strong>(8) with a <em>reload</em> command which uses <em>nscd -i</em> to purge the cache. That use of the word &quot;reload&quot; is entirely different from the &quot;reloading&quot; described here.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>nscd</strong>(8)</p>',53))])}const b=o(c,[["render",m]]);export{g as __pageData,b as default};
